import java.util.*;class PhoneDirectory{Queue<Integer>q=new ArrayDeque<>();boolean[]used;public PhoneDirectory(int n){used=new boolean[n];for(int i=0;i<n;i++)q.add(i);}public int get(){if(q.isEmpty())return-1;int x=q.remove();used[x]=true;return x;}public boolean check(int n){return n>=0&&n<used.length&&!used[n];}public void release(int n){if(n>=0&&n<used.length&&used[n]){used[n]=false;q.add(n);}}}
